      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A card fills a definite width and shrinks to fit an indefinite one —\n'
      '    // CSS\'s own block-box rule. So a card inside a horizontal list sizes to\n'
      '    // its content instead of asserting.\n'
      '    return SizedBox(\n'
      '      height: 96,\n'
      '      child: ListView(\n'
      '        scrollDirection: Axis.horizontal,\n'
      '        children: <Widget>[\n'
