  // examples/checkbox_examples.dart
  'checkbox_tristate':
      'class CheckboxTristateExample extends StatefulWidget {\n'
      '  const CheckboxTristateExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<CheckboxTristateExample> createState() =>\n'
      '      _CheckboxTristateExampleState();\n'
      '}\n'
      '\n'
      'class _CheckboxTristateExampleState extends State<CheckboxTristateExample> {\n'
      '  static const List<String> _all = <String>[\'read\', \'write\', \'admin\'];\n'
      '  final Set<String> _scopes = <String>{\'read\'};\n'
      '\n'
      '  /// Indeterminate is what a parent looks like when only some of its children\n'
      '  /// are on — the case the tri-state constructor exists for.\n'
      '  AstryxCheckboxValue get _parent => switch (_scopes.length) {\n'
      '    0 => AstryxCheckboxValue.unchecked,\n'
      '    3 => AstryxCheckboxValue.checked,\n'
      '    _ => AstryxCheckboxValue.indeterminate,\n'
      '  };\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        AstryxCheckbox.tristate(\n'
      '          label: \'All scopes\',\n'
      '          value: _parent,\n'
      '          onChanged: (value) => setState(() {\n'
      '            _scopes\n'
      '              ..clear()\n'
      '              ..addAll(\n'
      '                value == AstryxCheckboxValue.checked ? _all : const <String>[],\n'
      '              );\n'
      '          }),\n'
      '        ),\n'
      '        Padding(\n'
      '          padding: const EdgeInsetsDirectional.only(start: 28),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              for (final scope in _all)\n'
      '                AstryxCheckbox(\n'
      '                  label: scope,\n'
      '                  value: _scopes.contains(scope),\n'
      '                  onChanged: (value) => setState(() {\n'
      '                    if (value) {\n'
      '                      _scopes.add(scope);\n'
      '                    } else {\n'
      '                      _scopes.remove(scope);\n'
      '                    }\n'
      '                  }),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
