  // examples/checkbox_examples.dart
  'checkbox_states':
      'class CheckboxStatesExample extends StatelessWidget {\n'
      '  const CheckboxStatesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        AstryxCheckbox(label: \'Disabled\', value: true, enabled: false),\n'
      '        // Read-only is not disabled: the value still means something, it is\n'
      '        // just not yours to change here. So it is not dimmed.\n'
      '        AstryxCheckbox(label: \'Read-only\', value: true, readOnly: true),\n'
      '        AstryxCheckbox(label: \'Saving\', value: true, loading: true),\n'
      '        AstryxCheckbox(\n'
