  // examples/collapsible_examples.dart
  'collapsible_controlled':
      'class CollapsibleControlledExample extends StatefulWidget {\n'
      '  const CollapsibleControlledExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<CollapsibleControlledExample> createState() =>\n'
      '      _CollapsibleControlledExampleState();\n'
      '}\n'
      '\n'
      'class _CollapsibleControlledExampleState\n'
      '    extends State<CollapsibleControlledExample> {\n'
      '  final AstryxCollapsibleController _controller = AstryxCollapsibleController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // With a controller the state is yours: anything can open the section, and\n'
      '    // you can watch it. Dispose one you own.\n'
      '    return SizedBox(\n'
      '      width: 360,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(label: \'Expand\', onPressed: _controller.expand),\n'
      '              AstryxButton(label: \'Collapse\', onPressed: _controller.collapse),\n'
      '            ],\n'
      '          ),\n'
      '          AstryxCollapsible(\n'
      '            controller: _controller,\n'
      '            title: \'Request headers\',\n'
      '            child: const AstryxText(\n'
      '              \'Accept: application/json\\nX-Request-Id: 9f2c…\',\n'
      '              type: AstryxTextType.code,\n'
      '            ),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
