      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The dialog is a widget in the tree, not a `showDialog` call. It renders\n'
      '    // nothing until its controller opens it — so it can sit next to whatever\n'
      '    // opens it, and the state that drives it stays yours.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(\n'
      '          label: \'Delete project\',\n'
      '          variant: AstryxButtonVariant.destructive,\n'
      '          onPressed: _controller.show,\n'
      '        ),\n'
      '        AstryxDialog(\n'
      '          controller: _controller,\n'
      '          title: \'Delete project\',\n'
      '          description: \'This cannot be undone.\',\n'
      '          footer: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.end,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(label: \'Cancel\', onPressed: _controller.hide),\n'
      '              AstryxButton(\n'
      '                label: \'Delete\',\n'
      '                variant: AstryxButtonVariant.destructive,\n'
      '                onPressed: _controller.hide,\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          child: const AstryxText(\n'
      '            \'Everything in this project will be permanently removed, \'\n'
      '            \'including its request history.\',\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
