  // examples/dialog_examples.dart
  'dialog_scrolling':
      'class DialogScrollingExample extends StatefulWidget {\n'
      '  const DialogScrollingExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DialogScrollingExample> createState() =>\n'
      '      _DialogScrollingExampleState();\n'
      '}\n'
      '\n'
      'class _DialogScrollingExampleState extends State<DialogScrollingExample> {\n'
      '  final AstryxDialogController _controller = AstryxDialogController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The body scrolls; the header and footer do not. A long dialog never\n'
      '    // pushes its actions off the screen.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(label: \'Terms of service\', onPressed: _controller.show),\n'
      '        AstryxDialog(\n'
      '          controller: _controller,\n'
      '          title: \'Terms of service\',\n'
      '          description: \'Last updated 4 March.\',\n'
      '          footer: AstryxButton(\n'
      '            label: \'Accept\',\n'
      '            variant: AstryxButtonVariant.primary,\n'
      '            onPressed: _controller.hide,\n'
      '          ),\n'
      '          child: AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              for (var clause = 1; clause <= 30; clause++)\n'
      '                AstryxText(\'Clause \$clause. Everything in moderation.\'),\n'
      '            ],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/dialog_examples.dart
  'dialog_blocking':
      'class DialogBlockingExample extends StatefulWidget {\n'
      '  const DialogBlockingExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DialogBlockingExample> createState() => _DialogBlockingExampleState();\n'
      '}\n'
      '\n'
      'class _DialogBlockingExampleState extends State<DialogBlockingExample> {\n'
      '  final AstryxDialogController _controller = AstryxDialogController();\n'
      '  String _outcome = \'—\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _answer(String outcome) {\n'
      '    setState(() => _outcome = outcome);\n'
      '    _controller.hide();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // No barrier dismissal, no Escape, no close button — the choice has to be\n'
      '    // made. Be certain it does before reaching for this.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(label: \'Migrate data\', onPressed: _controller.show),\n'
      '        AstryxText(\n'
      '          \'Outcome: \$_outcome\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '        AstryxDialog(\n'
      '          controller: _controller,\n'
      '          title: \'Keep or discard the old rows?\',\n'
      '          showCloseButton: false,\n'
      '          barrierDismissible: false,\n'
      '          escapeDismissible: false,\n'
      '          footer: AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            justify: AstryxStackJustify.end,\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(\n'
      '                label: \'Discard\',\n'
      '                variant: AstryxButtonVariant.destructive,\n'
      '                onPressed: () => _answer(\'Discarded\'),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'Keep\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                onPressed: () => _answer(\'Kept\'),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          child: const AstryxText(\n'
      '            \'The migration cannot run twice, so this decision is final.\',\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
