  // examples/forms_advanced_examples.dart
  'complex_selector_demo':
      'class ComplexSelectorDemoExample extends StatefulWidget {\n'
      '  const ComplexSelectorDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ComplexSelectorDemoExample> createState() =>\n'
      '      _ComplexSelectorDemoExampleState();\n'
      '}\n'
      '\n'
      'class _ComplexSelectorDemoExampleState\n'
      '    extends State<ComplexSelectorDemoExample> {\n'
      '  AstryxPalette? _palette;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A surface a list of options cannot express: a grid of swatches. The\n'
      '    // package supplies the field, the trigger and the overlay; the contents are\n'
      '    // entirely the caller\'s.\n'
      '    return AstryxComplexSelector<AstryxPalette?>(\n'
      '      label: \'Label colour\',\n'
      '      value: _palette,\n'
      '      placeholder: \'No colour\',\n'
      '      triggerLabel: _palette == null\n'
      '          ? null\n'
      '          : AstryxBadge(\n'
      '              _palette!.name,\n'
      '              variant: AstryxBadgeVariant.palette(_palette!),\n'
      '            ),\n'
      '      onChanged: (value) => setState(() => _palette = value),\n'
      '      surfaceBuilder: (context, state) => Padding(\n'
      '        padding: const EdgeInsets.all(8),\n'
      '        child: AstryxGrid(\n'
      '          minWidth: 96,\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            for (final palette in AstryxPalette.values)\n'
      '              AstryxButton(\n'
      '                label: palette.name,\n'
      '                variant: AstryxButtonVariant.ghost,\n'
      '                size: AstryxButtonSize.sm,\n'
      '                leading: AstryxBadge(\n'
      '                  \'  \',\n'
      '                  variant: AstryxBadgeVariant.palette(palette),\n'
      '                ),\n'
      '                onPressed: () {\n'
      '                  state.onChanged(palette);\n'
      '                  state.close();\n'
      '                },\n'
      '              ),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
