      '    // The status belongs to the group: "pick at least one" is not a complaint\n'
      '    // about any single row, and repeating it on each would be three times the\n'
      '    // noise for a screen reader.\n'
      '    return const AstryxCheckboxList<String>(\n'
      '      label: \'Regions\',\n'
      '      values: <String>{},\n'
      '      required: true,\n'
      '      status: AstryxFieldStatus.error(\'Choose at least one region.\'),\n'
      '      options: <AstryxCheckboxOption<String>>[\n'
      '        AstryxCheckboxOption(value: \'us\', label: \'us-east-1\'),\n'
      '        AstryxCheckboxOption(value: \'eu\', label: \'eu-west-2\'),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
