  // examples/grid_examples.dart
  'grid_repeat':
      'class GridRepeatExample extends StatelessWidget {\n'
      '  const GridRepeatExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Five items in a four-column track list leave one short row. `fit`\n'
      '    // stretches it; `fill` keeps the empty tracks, so the last item stays the\n'
      '    // width it would have had in a full row.\n'
      '    return const AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxText(\'repeat: fit\', type: AstryxTextType.label),\n'
      '        AstryxGrid(\n'
      '          minWidth: 140,\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            _Metric(\'One\', \'1\'),\n'
      '            _Metric(\'Two\', \'2\'),\n'
      '            _Metric(\'Three\', \'3\'),\n'
      '            _Metric(\'Four\', \'4\'),\n'
      '            _Metric(\'Five\', \'5\'),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\'repeat: fill\', type: AstryxTextType.label),\n'
      '        AstryxGrid(\n'
      '          minWidth: 140,\n'
      '          repeat: AstryxGridRepeat.fill,\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            _Metric(\'One\', \'1\'),\n'
      '            _Metric(\'Two\', \'2\'),\n'
      '            _Metric(\'Three\', \'3\'),\n'
      '            _Metric(\'Four\', \'4\'),\n'
      '            _Metric(\'Five\', \'5\'),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
