      'class IconRegistryExample extends StatelessWidget {\n'
      '  const IconRegistryExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Every semantic name the default registry knows. A theme can swap the\n'
      '    // glyphs behind these names without a single call site changing.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 150,\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        for (final name in AstryxIconName.values)\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxIcon(name, size: AstryxIconSize.sm),\n'
      '              Flexible(\n'
      '                child: AstryxText(\n'
      '                  name.name,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                  maxLines: 1,\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/icon_examples.dart
  'icon_labelled':
      'class IconLabelledExample extends StatelessWidget {\n'
      '  const IconLabelledExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return const AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing4,\n'
      '      children: <Widget>[\n'
      '        // Decorative: no label, so assistive technology skips it entirely.\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing1,\n'
      '          children: <Widget>[\n'
      '            AstryxIcon(AstryxIconName.clock),\n'
      '            AstryxText(\'Pending review\'),\n'
      '          ],\n'
      '        ),\n'
      '        // Meaningful on its own: it needs a name, because nothing else in the\n'
      '        // row says what it means.\n'
      '        AstryxIcon(\n'
      '          AstryxIconName.warning,\n'
      '          color: AstryxIconColor.warning,\n'
      '          label: \'Quota nearly reached\',\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/icons_examples.dart
  'icons_registry_swap':
      'class IconsRegistrySwapExample extends StatelessWidget {\n'
      '  const IconsRegistrySwapExample({super.key});\n'
      '\n'
      '  /// Built from the defaults, so the 25 names not listed still resolve.\n'
      '  static final AstryxIconRegistry _custom = AstryxIconRegistry.defaults\n'
      '      .copyWith(const <AstryxIconName, IconData>{\n'
      '        AstryxIconName.close: LucideIcons.circleX,\n'
      '        AstryxIconName.check: LucideIcons.badgeCheck,\n'
      '        AstryxIconName.chevronRight: LucideIcons.arrowRight,\n'
      '      });\n'
      '\n'
      '  static const List<AstryxIconName> _shown = <AstryxIconName>[\n'
      '    AstryxIconName.close,\n'
      '    AstryxIconName.check,\n'
      '    AstryxIconName.chevronRight,\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxGrid(\n'
      '      minWidth: 220,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (title, registry) in <(String, AstryxIconRegistry)>[\n'
      '          (\'AstryxIconRegistry.defaults\', AstryxIconRegistry.defaults),\n'
      '          (\'defaults.copyWith(…)\', _custom),\n'
      '        ])\n'
      '          // `AstryxTheme` rather than a nested provider: this swaps the\n'
      '          // registry and inherits everything else, so the theme and density\n'
      '          // pickers above still reach the icons below.\n'
      '          AstryxTheme(\n'
      '            data: AstryxTheme.of(context),\n'
      '            density: AstryxTheme.densityOf(context),\n'
      '            icons: registry,\n'
      '            child: AstryxCard(\n'
      '              padding: AstryxSpacingToken.spacing3,\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(\n'
      '                    title,\n'
      '                    type: AstryxTextType.code,\n'
      '                    color: AstryxTextColor.secondary,\n'
      '                    maxLines: 1,\n'
      '                  ),\n'
      '                  AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing4,\n'
      '                    children: <Widget>[\n'
      '                      for (final name in _shown)\n'
      '                        AstryxIcon(name, size: AstryxIconSize.lg),\n'
      '                    ],\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/icons_examples.dart
  'icons_mirroring':
      'class IconsMirroringExample extends StatelessWidget {\n'
      '  const IconsMirroringExample({super.key});\n'
      '\n'
      '  /// Two that mirror, and two that deliberately do not.\n'
      '  static const List<(AstryxIconName, String)> _cases =\n'
      '      <(AstryxIconName, String)>[\n'
      '        (AstryxIconName.chevronRight, \'mirrors\'),\n'
      '        (AstryxIconName.externalLink, \'mirrors\'),\n'
      '        (AstryxIconName.arrowUp, \'block axis — never flips\'),\n'
      '        (AstryxIconName.clock, \'an object — never flips\'),\n'
      '      ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxGrid(\n'
      '      minWidth: 190,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (name, note) in _cases)\n'
      '          AstryxCard(\n'
      '            padding: AstryxSpacingToken.spacing3,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxText(name.name, type: AstryxTextType.code, maxLines: 1),\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing4,\n'
      '                  children: <Widget>[\n'
      '                    for (final direction in TextDirection.values)\n'
      '                      AstryxHStack(\n'
      '                        gap: AstryxSpacingToken.spacing1,\n'
      '                        children: <Widget>[\n'
      '                          AstryxText(\n'
      '                            direction.name,\n'
      '                            type: AstryxTextType.supporting,\n'
      '                            color: AstryxTextColor.secondary,\n'
      '                          ),\n'
      '                          Directionality(\n'
      '                            textDirection: direction,\n'
      '                            child: AstryxIcon(name),\n'
      '                          ),\n'
      '                        ],\n'
      '                      ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  note,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/layout_examples.dart
  'layout_page':
      'class LayoutPageExample extends StatelessWidget {\n'
      '  const LayoutPageExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A screen is a measure, a column of sections, and a grid inside one of\n'
      '    // them. There is no page widget to learn: the same four layout primitives\n'
      '    // that build a card build the page around it.\n'
      '    return AstryxCenter(\n'
      '      axis: AstryxCenterAxis.horizontal,\n'
      '      maxWidth: 760,\n'
      '      paddingBlock: AstryxSpacingToken.spacing6,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing6,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxHStack(\n'
      '            mainAxisSize: MainAxisSize.max,\n'
      '            justify: AstryxStackJustify.between,\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            children: <Widget>[\n'
      '              const Flexible(\n'
      '                child: AstryxHeading(\'Environments\', level: 1),\n'
      '              ),\n'
      '              AstryxButton(\n'
      '                label: \'New environment\',\n'
      '                variant: AstryxButtonVariant.primary,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '          const AstryxDivider(),\n'
      '          AstryxGrid(\n'
      '            minWidth: 200,\n'
      '            gap: AstryxSpacingToken.spacing3,\n'
      '            children: <Widget>[\n'
      '              for (final (name, status) in const <(String, String)>[\n'
      '                (\'production\', \'healthy\'),\n'
      '                (\'staging\', \'degraded\'),\n'
      '                (\'preview\', \'healthy\'),\n'
      '              ])\n'
      '                AstryxCard(\n'
      '                  child: AstryxVStack(\n'
      '                    gap: AstryxSpacingToken.spacing2,\n'
      '                    children: <Widget>[\n'
      '                      AstryxText(name, type: AstryxTextType.label),\n'
      '                      AstryxBadge(\n'
      '                        status,\n'
      '                        variant: status == \'healthy\'\n'
      '                            ? AstryxBadgeVariant.success\n'
      '                            : AstryxBadgeVariant.warning,\n'
      '                      ),\n'
      '                    ],\n'
      '                  ),\n'
      '                ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/motion_examples.dart
  'motion_durations':
      'class MotionDurationsExample extends StatefulWidget {\n'
      '  const MotionDurationsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<MotionDurationsExample> createState() => _MotionDurationsExampleState();\n'
      '}\n'
      '\n'
      'class _MotionDurationsExampleState extends State<MotionDurationsExample> {\n'
      '  /// The three bases. Each has a `-min` and a `-max` variant beside it.\n'
      '  static const List<AstryxDurationToken> _bases = <AstryxDurationToken>[\n'
      '    AstryxDurationToken.fast,\n'
      '    AstryxDurationToken.medium,\n'
      '    AstryxDurationToken.slow,\n'
      '  ];\n'
      '\n'
      '  bool _moved = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // Durations come from `AstryxMotion`, never from the theme directly: it is\n'
      '    // the layer that returns zero when the platform asks for reduced motion.\n'
      '    final motion = AstryxMotion.of(context);\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final token in _bases)\n'
      '          AstryxVStack(\n'
      '            gap: AstryxSpacingToken.spacing1,\n'
      '            align: AstryxStackAlign.stretch,\n'
      '            children: <Widget>[\n'
      '              AstryxText(\n'
      '                \'\${token.name} · \${motion.duration(token).inMilliseconds}ms\',\n'
      '                type: AstryxTextType.code,\n'
      '              ),\n'
      '              DecoratedBox(\n'
      '                decoration: BoxDecoration(\n'
      '                  color: theme.color(AstryxColorToken.backgroundMuted),\n'
      '                  borderRadius: theme.borderRadius(AstryxRadiusToken.full),\n'
      '                ),\n'
      '                child: SizedBox(\n'
      '                  height: 28,\n'
      '                  child: AnimatedAlign(\n'
      '                    duration: motion.duration(token),\n'
      '                    curve: motion.curve(),\n'
      '                    alignment: _moved\n'
      '                        ? AlignmentDirectional.centerEnd\n'
      '                        : AlignmentDirectional.centerStart,\n'
      '                    child: Padding(\n'
      '                      padding: EdgeInsets.symmetric(\n'
      '                        horizontal: theme.spacing(AstryxSpacingToken.spacing1),\n'
      '                      ),\n'
      '                      child: DecoratedBox(\n'
      '                        decoration: BoxDecoration(\n'
      '                          color: theme.color(AstryxColorToken.accent),\n'
      '                          borderRadius: theme.borderRadius(\n'
      '                            AstryxRadiusToken.full,\n'
      '                          ),\n'
      '                        ),\n'
      '                        child: const SizedBox(width: 20, height: 20),\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        AstryxHStack(\n'
      '          gap: AstryxSpacingToken.spacing2,\n'
      '          children: <Widget>[\n'
      '            AstryxButton(\n'
      '              label: _moved ? \'Send back\' : \'Send across\',\n'
      '              onPressed: () => setState(() => _moved = !_moved),\n'
      '            ),\n'
      '          ],\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/overlay_examples.dart
  'overlay_demo':
      'class OverlayDemoExample extends StatefulWidget {\n'
      '  const OverlayDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<OverlayDemoExample> createState() => _OverlayDemoExampleState();\n'
      '}\n'
      '\n'
      'class _OverlayDemoExampleState extends State<OverlayDemoExample> {\n'
      '  final AstryxOverlayController _controller = AstryxOverlayController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The modal contract with nothing on top of it: scrim, focus trap, Escape,\n'
      '    // barrier dismissal. What sits on the layer is entirely yours.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(label: \'Open preview\', onPressed: _controller.show),\n'
      '        AstryxOverlay(\n'
      '          controller: _controller,\n'
      '          label: \'Preview\',\n'
      '          child: AstryxCard(\n'
      '            width: 320,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\n'
      '                  \'atlas-scheduler.png\',\n'
      '                  type: AstryxHeadingType.display3,\n'
      '                ),\n'
      '                const AstryxSkeleton(height: 120),\n'
      '                AstryxButton(label: \'Close\', onPressed: _controller.hide),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/overlay_examples.dart
  'overlay_placement':
      'class OverlayPlacementExample extends StatefulWidget {\n'
      '  const OverlayPlacementExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<OverlayPlacementExample> createState() =>\n'
      '      _OverlayPlacementExampleState();\n'
      '}\n'
      '\n'
      'class _OverlayPlacementExampleState extends State<OverlayPlacementExample> {\n'
      '  final AstryxOverlayController _controller = AstryxOverlayController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `alignment` puts the layer anywhere in the viewport: bottom-centre is a\n'
      '    // sheet, top-centre is a command palette, centre is a dialog.\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(label: \'Open sheet\', onPressed: _controller.show),\n'
      '        AstryxOverlay(\n'
      '          controller: _controller,\n'
      '          label: \'Filters\',\n'
      '          alignment: Alignment.bottomCenter,\n'
      '          transition: AstryxOverlayTransition.fade,\n'
      '          child: AstryxCard(\n'
      '            width: 360,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing3,\n'
      '              children: <Widget>[\n'
      '                const AstryxHeading(\n'
      '                  \'Filters\',\n'
      '                  type: AstryxHeadingType.display3,\n'
      '                ),\n'
      '                const AstryxText(\n'
      '                  \'A sheet is an overlay aligned to the bottom edge — not a \'\n'
      '                  \'separate component.\',\n'
      '                ),\n'
      '                AstryxButton(label: \'Apply\', onPressed: _controller.hide),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/platform_examples.dart
  'platform_targets':
      '/// One target, and what the package resolves for it.\n'
      '///\n'
      '/// The glyphs come from Lucide directly rather than from `AstryxIconName`,\n'
      '/// which names only what the widget set itself needs. Every icon slot takes a\n'
      '/// `Widget`, so an application\'s own icons go in the same way.\n'
      'typedef _Target = ({\n'
      '  String name,\n'
      '  IconData icon,\n'
      '  String density,\n'
      '  AstryxPalette palette,\n'
      '  String note,\n'
      '});\n'
      '\n'
      'const List<_Target> _targets = <_Target>[\n'
      '  (\n'
      '    name: \'Android\',\n'
      '    icon: LucideIcons.smartphone,\n'
      '    density: \'touch\',\n'
      '    palette: AstryxPalette.blue,\n'
      '    note: \'48px tap targets, hover suppressed.\',\n'
      '  ),\n'
      '  (\n'
      '    name: \'iOS\',\n'
      '    icon: LucideIcons.tabletSmartphone,\n'
      '    density: \'touch\',\n'
      '    palette: AstryxPalette.blue,\n'
      '    note: \'The same, and the same tap target.\',\n'
      '  ),\n'
      '  (\n'
      '    name: \'macOS\',\n'
      '    icon: LucideIcons.laptop,\n'
      '    density: \'pointer\',\n'
      '    palette: AstryxPalette.purple,\n'
      '    note: \'Menlo heads the monospace stack.\',\n'
      '  ),\n'
      '  (\n'
      '    name: \'Windows\',\n'
      '    icon: LucideIcons.monitor,\n'
      '    density: \'pointer\',\n'
      '    palette: AstryxPalette.purple,\n'
      '    note: \'Consolas heads the monospace stack.\',\n'
      '  ),\n'
      '  (\n'
      '    name: \'Linux\',\n'
      '    icon: LucideIcons.terminal,\n'
      '    density: \'pointer\',\n'
      '    palette: AstryxPalette.purple,\n'
      '    note: \'The generic families stand.\',\n'
      '  ),\n'
      '  (\n'
      '    name: \'Fuchsia\',\n'
      '    icon: LucideIcons.cpu,\n'
      '    density: \'pointer\',\n'
      '    palette: AstryxPalette.purple,\n'
      '    note: \'Resolved, though untested in the wild.\',\n'
      '  ),\n'
      '  (\n'
      '    name: \'Web\',\n'
      '    icon: LucideIcons.globe,\n'
      '    density: \'either\',\n'
      '    palette: AstryxPalette.gray,\n'
      '    note: \'Pointer precision decides, not the host OS.\',\n'
      '  ),\n'
      '];\n'
      '\n'
      'class PlatformTargetsExample extends StatelessWidget {\n'
      '  const PlatformTargetsExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    return AstryxGrid(\n'
      '      minWidth: 190,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final target in _targets)\n'
      '          AstryxCard(\n'
      '            padding: AstryxSpacingToken.spacing3,\n'
      '            child: AstryxVStack(\n'
      '              gap: AstryxSpacingToken.spacing2,\n'
      '              align: AstryxStackAlign.stretch,\n'
      '              children: <Widget>[\n'
      '                AstryxHStack(\n'
      '                  gap: AstryxSpacingToken.spacing2,\n'
      '                  children: <Widget>[\n'
      '                    // Decorative: the name is right beside it, so announcing\n'
      '                    // the glyph as well would say everything twice.\n'
      '                    ExcludeSemantics(\n'
      '                      child: Icon(\n'
      '                        target.icon,\n'
      '                        size: AstryxIconSize.lg.pixels,\n'
      '                        color: theme.color(AstryxColorToken.iconSecondary),\n'
      '                      ),\n'
      '                    ),\n'
      '                    Flexible(\n'
      '                      child: AstryxText(\n'
      '                        target.name,\n'
      '                        type: AstryxTextType.label,\n'
      '                        maxLines: 1,\n'
      '                      ),\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxHStack(\n'
      '                  children: <Widget>[\n'
      '                    AstryxBadge(\n'
      '                      target.density,\n'
      '                      variant: AstryxBadgeVariant.palette(target.palette),\n'
      '                    ),\n'
      '                  ],\n'
      '                ),\n'
      '                AstryxText(\n'
      '                  target.note,\n'
      '                  type: AstryxTextType.supporting,\n'
      '                  color: AstryxTextColor.secondary,\n'
      '                ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/popover_examples.dart
  'popover_demo':
      'class PopoverDemoExample extends StatelessWidget {\n'
      '  const PopoverDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxPopover(\n'
      '      label: \'Filters\',\n'
      '      width: 260,\n'
      '      content: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxHeading(\'Filters\', level: 5),\n'
      '          const AstryxTextInput(label: \'Owner\', placeholder: \'Anyone\'),\n'
      '          AstryxButton(\n'
      '            label: \'Apply\',\n'
      '            variant: AstryxButtonVariant.primary,\n'
      '            onPressed: () {},\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '      // A builder, not a child: a button consumes its own taps, so the popover\n'
      '      // hands you the controller and lets you wire it where it belongs.\n'
      '      triggerBuilder: (context, controller) =>\n'
      '          AstryxButton(label: \'Filters\', onPressed: controller.toggle),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/popover_examples.dart
  'popover_sides':
      'class PopoverSidesExample extends StatelessWidget {\n'
      '  const PopoverSidesExample({super.key});\n'
