      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // Three steps of the scale, nested in the order they are meant to nest:\n'
      '    // container outside, element inside it, inner innermost. Each step is one\n'
      '    // notch tighter than the one around it, so the curves stay concentric.\n'
      '    return AstryxCard(\n'
      '      padding: AstryxSpacingToken.spacing3,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing2,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxText(\'container · card\', type: AstryxTextType.label),\n'
      '          DecoratedBox(\n'
      '            decoration: BoxDecoration(\n'
      '              color: theme.color(AstryxColorToken.backgroundMuted),\n'
