  // examples/status_dot_examples.dart
  'status_dot_demo':
      'class StatusDotDemoExample extends StatelessWidget {\n'
      '  const StatusDotDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The dot is never the whole message: the words beside it are what a\n'
      '    // reader who cannot tell green from amber relies on.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final (variant, label) in const <(AstryxStatusDotVariant, String)>[\n'
      '          (AstryxStatusDotVariant.success, \'Healthy\'),\n'
      '          (AstryxStatusDotVariant.warning, \'Degraded\'),\n'
      '          (AstryxStatusDotVariant.error, \'Unreachable\'),\n'
      '          (AstryxStatusDotVariant.accent, \'Deploying\'),\n'
      '          (AstryxStatusDotVariant.neutral, \'Not configured\'),\n'
      '        ])\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxStatusDot(variant, label: label),\n'
      '              AstryxText(label),\n'
      '            ],\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/status_dot_examples.dart
  'status_dot_in_place':
      'class StatusDotInPlaceExample extends StatelessWidget {\n'
      '  const StatusDotInPlaceExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Where a dot earns its keep: a list of rows whose text already says what\n'
      '    // the state is, so the dot only has to make it scannable.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
