      'class _TabListOverflowExampleState extends State<TabListOverflowExample> {\n'
      '  int _tab = 0;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Too many tabs scroll rather than shrink, with a fade at whichever edge\n'
      '    // has more. Arrowing to an off-screen tab scrolls it into view — a\n'
      '    // selection you cannot see is worse than none.\n'
      '    return SizedBox(\n'
      '      width: 360,\n'
      '      child: AstryxTabList<int>(\n'
      '        value: _tab,\n'
      '        onChanged: (value) => setState(() => _tab = value),\n'
      '        tabs: <AstryxTab<int>>[\n'
      '          for (var i = 0; i < 16; i++)\n'
      '            AstryxTab<int>(value: i, label: \'Section \$i\'),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
