  // examples/text_input_examples.dart
  'text_input_validation':
      'class TextInputValidationExample extends StatefulWidget {\n'
      '  const TextInputValidationExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TextInputValidationExample> createState() =>\n'
      '      _TextInputValidationExampleState();\n'
      '}\n'
      '\n'
      'class _TextInputValidationExampleState\n'
      '    extends State<TextInputValidationExample> {\n'
      '  final TextEditingController _email = TextEditingController();\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _email.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  /// Validate on change here so the example reacts as you type. In a real form,\n'
      '  /// validating on blur or on submit is usually kinder.\n'
      '  AstryxFieldStatus? get _status {\n'
      '    final value = _email.text.trim();\n'
      '    if (value.isEmpty) return null;\n'
      '    return value.contains(\'@\')\n'
      '        ? const AstryxFieldStatus.success(\'That looks right\')\n'
      '        : const AstryxFieldStatus.error(\'Enter a valid email address\');\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return SizedBox(\n'
      '      width: 320,\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          AstryxTextInput(\n'
      '            label: \'Email\',\n'
      '            controller: _email,\n'
      '            required: true,\n'
      '            placeholder: \'you@example.com\',\n'
      '            status: _status,\n'
      '            keyboardType: TextInputType.emailAddress,\n'
      '            onChanged: (_) => setState(() {}),\n'
      '          ),\n'
      '          const AstryxTextInput(\n'
      '            label: \'Subdomain\',\n'
      '            optional: true,\n'
      '            status: AstryxFieldStatus.warning(\'This name is nearly taken\'),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
