  // examples/theming_examples.dart
  'theming_themes':
      'class ThemingThemesExample extends StatelessWidget {\n'
      '  const ThemingThemesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Every theme is a value. Nesting a provider re-themes a subtree, which is\n'
      '    // how a preview like this one can show all seven at once.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 150,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final theme in <(String, AstryxDefinedTheme)>[\n'
      '          (\'neutral\', neutralTheme),\n'
      '          (\'matcha\', matchaTheme),\n'
      '          (\'stone\', stoneTheme),\n'
      '          (\'gothic\', gothicTheme),\n'
      '          (\'chocolate\', chocolateTheme),\n'
      '          (\'y2k\', y2kTheme),\n'
      '          (\'butter\', butterTheme),\n'
      '          (\'acme (custom)\', acmeTheme),\n'
      '        ])\n'
      '          AstryxThemeProvider(\n'
      '            theme: theme.\$2,\n'
      '            child: AstryxCard(\n'
      '              padding: AstryxSpacingToken.spacing3,\n'
      '              child: AstryxVStack(\n'
      '                gap: AstryxSpacingToken.spacing2,\n'
      '                align: AstryxStackAlign.stretch,\n'
      '                children: <Widget>[\n'
      '                  AstryxText(theme.\$1, type: AstryxTextType.label),\n'
      '                  AstryxButton(\n'
      '                    label: \'Primary\',\n'
      '                    variant: AstryxButtonVariant.primary,\n'
      '                    size: AstryxButtonSize.sm,\n'
      '                    onPressed: () {},\n'
      '                  ),\n'
      '                  const AstryxHStack(\n'
      '                    gap: AstryxSpacingToken.spacing1,\n'
      '                    wrap: true,\n'
      '                    runGap: AstryxSpacingToken.spacing1,\n'
      '                    children: <Widget>[\n'
      '                      AstryxBadge(\'A\', variant: AstryxBadgeVariant.info),\n'
      '                      AstryxBadge(\'B\', variant: AstryxBadgeVariant.success),\n'
      '                      AstryxBadge(\'C\', variant: AstryxBadgeVariant.error),\n'
      '                    ],\n'
      '                  ),\n'
      '                ],\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/theming_examples.dart
  'theming_modes':
      'class ThemingModesExample extends StatelessWidget {\n'
      '  const ThemingModesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `mode` defaults to `system`, which tracks the platform\'s own preference\n'
      '    // through `MediaQuery` — no rebuild of your own required.\n'
      '    return AstryxGrid(\n'
      '      minWidth: 200,\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        for (final mode in <AstryxColorMode>[\n'
      '          AstryxColorMode.light,\n'
      '          AstryxColorMode.dark,\n'
      '        ])\n'
