  // examples/toast_examples.dart
  'toast_demo':
      'class ToastDemoExample extends StatelessWidget {\n'
      '  const ToastDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `AstryxThemeProvider` and `AstryxApp` install the host, so there is\n'
      '    // nothing to wire: reach for the scope and show one.\n'
      '    return AstryxButton(\n'
      '      label: \'Archive project\',\n'
      '      onPressed: () => AstryxToastScope.of(\n'
      '        context,\n'
      '      ).show(const AstryxToast(message: \'Project archived\')),\n'
      '    );\n'
      '  }\n'
      '}\n',
