  // examples/toast_examples.dart
  'toast_duration':
      'class ToastDurationExample extends StatelessWidget {\n'
      '  const ToastDurationExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      wrap: true,\n'
      '      children: <Widget>[\n'
      '        AstryxButton(\n'
      '          label: \'Two seconds\',\n'
      '          onPressed: () => AstryxToastScope.of(context).show(\n'
      '            const AstryxToast(\n'
      '              message: \'Gone in two\',\n'
      '              duration: Duration(seconds: 2),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        // `Duration.zero` pins it until the user dismisses it. Hover or focus\n'
      '        // also pauses the timeout — a toast must not vanish while someone is\n'
      '        // reaching for its Undo.\n'
      '        AstryxButton(\n'
      '          label: \'Until dismissed\',\n'
      '          onPressed: () => AstryxToastScope.of(context).show(\n'
      '            const AstryxToast(\n'
      '              message: \'Pinned until dismissed\',\n'
      '              duration: Duration.zero,\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: \'Not dismissible\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          onPressed: () => AstryxToastScope.of(context).show(\n'
      '            const AstryxToast(\n'
      '              message: \'No dismiss button, five seconds\',\n'
      '              dismissible: false,\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toast_examples.dart
  'toast_queue':
      'class ToastQueueExample extends StatelessWidget {\n'
      '  const ToastQueueExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        // Beyond `maxVisible` (five by default) the rest queue and take their\n'
      '        // turn, rather than burying the screen.\n'
      '        AstryxButton(\n'
      '          label: \'Show eight\',\n'
      '          onPressed: () {\n'
      '            final toasts = AstryxToastScope.of(context);\n'
      '            for (var i = 1; i <= 8; i++) {\n'
      '              toasts.show(AstryxToast(message: \'Notification \$i\'));\n'
      '            }\n'
      '          },\n'
      '        ),\n'
      '        AstryxButton(\n'
      '          label: \'Clear\',\n'
      '          variant: AstryxButtonVariant.ghost,\n'
      '          onPressed: () => AstryxToastScope.of(context).clear(),\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toggle_button_examples.dart
  'toggle_button_demo':
      'class ToggleButtonDemoExample extends StatefulWidget {\n'
      '  const ToggleButtonDemoExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ToggleButtonDemoExample> createState() =>\n'
      '      _ToggleButtonDemoExampleState();\n'
      '}\n'
      '\n'
      'class _ToggleButtonDemoExampleState extends State<ToggleButtonDemoExample> {\n'
      '  bool _pressed = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The button owns no state. It reports the state it should move to, and the\n'
      '    // caller decides — the same contract as every other control here.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxToggleButton(\n'
      '          label: \'Only my issues\',\n'
      '          icon: const AstryxIcon(AstryxIconName.funnel),\n'
      '          pressed: _pressed,\n'
      '          onChanged: (value) => setState(() => _pressed = value),\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _pressed ? \'Showing 12 of 240 issues.\' : \'Showing all 240 issues.\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toggle_button_examples.dart
  'toggle_button_icon_only':
      'class ToggleButtonIconOnlyExample extends StatefulWidget {\n'
      '  const ToggleButtonIconOnlyExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ToggleButtonIconOnlyExample> createState() =>\n'
      '      _ToggleButtonIconOnlyExampleState();\n'
      '}\n'
      '\n'
      'class _ToggleButtonIconOnlyExampleState\n'
      '    extends State<ToggleButtonIconOnlyExample> {\n'
      '  bool _watching = false;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // `labelHidden` keeps the label as the accessible name and stops painting\n'
      '    // it: the button squares off and takes the label as its tooltip, so the\n'
      '    // glyph is never the only thing a reader has.\n'
      '    return AstryxToggleButton(\n'
      '      label: \'Watch this repository\',\n'
      '      labelHidden: true,\n'
      '      icon: const AstryxIcon(AstryxIconName.eyeSlash),\n'
      '      pressedIcon: const AstryxIcon(AstryxIconName.check),\n'
      '      pressed: _watching,\n'
      '      onChanged: (value) => setState(() => _watching = value),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toggle_button_examples.dart
  'toggle_button_group_single':
      'class ToggleButtonGroupSingleExample extends StatefulWidget {\n'
      '  const ToggleButtonGroupSingleExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ToggleButtonGroupSingleExample> createState() =>\n'
      '      _ToggleButtonGroupSingleExampleState();\n'
      '}\n'
      '\n'
      'class _ToggleButtonGroupSingleExampleState\n'
      '    extends State<ToggleButtonGroupSingleExample> {\n'
      '  String? _view = \'grid\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxToggleButtonGroup.single(\n'
      '          label: \'View mode\',\n'
      '          value: _view,\n'
      '          onChanged: (value) => setState(() => _view = value),\n'
      '          children: const <Widget>[\n'
      '            AstryxToggleButton(value: \'list\', label: \'List\'),\n'
      '            AstryxToggleButton(value: \'grid\', label: \'Grid\'),\n'
      '            AstryxToggleButton(value: \'board\', label: \'Board\'),\n'
      '          ],\n'
      '        ),\n'
      '        // Pressing the one that is already on clears the group, so "none" is\n'
      '        // always reachable — upstream\'s behaviour, and the reason the value is\n'
      '        // nullable.\n'
      '        AstryxText(\n'
      '          _view == null ? \'No view chosen.\' : \'Showing the \$_view view.\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toggle_button_examples.dart
  'toggle_button_group_multiple':
      'class ToggleButtonGroupMultipleExample extends StatefulWidget {\n'
      '  const ToggleButtonGroupMultipleExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ToggleButtonGroupMultipleExample> createState() =>\n'
      '      _ToggleButtonGroupMultipleExampleState();\n'
      '}\n'
      '\n'
      'class _ToggleButtonGroupMultipleExampleState\n'
      '    extends State<ToggleButtonGroupMultipleExample> {\n'
      '  Set<String> _statuses = <String>{\'failing\'};\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      children: <Widget>[\n'
      '        AstryxToggleButtonGroup.multiple(\n'
      '          label: \'Filter by status\',\n'
      '          values: _statuses,\n'
      '          // A new set arrives each time; the group never edits the one it was\n'
      '          // given.\n'
      '          onChanged: (values) => setState(() => _statuses = values),\n'
      '          children: const <Widget>[\n'
      '            AstryxToggleButton(value: \'passing\', label: \'Passing\'),\n'
      '            AstryxToggleButton(value: \'failing\', label: \'Failing\'),\n'
      '            AstryxToggleButton(value: \'queued\', label: \'Queued\'),\n'
      '          ],\n'
      '        ),\n'
      '        AstryxText(\n'
      '          _statuses.isEmpty\n'
      '              ? \'No filter: every run.\'\n'
      '              : \'Filtering: \${_statuses.join(\', \')}.\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toggle_button_examples.dart
  'toggle_button_group_vertical':
      'class ToggleButtonGroupVerticalExample extends StatefulWidget {\n'
      '  const ToggleButtonGroupVerticalExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<ToggleButtonGroupVerticalExample> createState() =>\n'
      '      _ToggleButtonGroupVerticalExampleState();\n'
      '}\n'
      '\n'
      'class _ToggleButtonGroupVerticalExampleState\n'
      '    extends State<ToggleButtonGroupVerticalExample> {\n'
      '  String? _environment = \'staging\';\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // A vertical group stretches its buttons to one width, so the labels line\n'
      '    // up however long they are.\n'
      '    return AstryxToggleButtonGroup.single(\n'
      '      label: \'Environment\',\n'
      '      value: _environment,\n'
      '      axis: Axis.vertical,\n'
      '      size: AstryxButtonSize.sm,\n'
      '      onChanged: (value) => setState(() => _environment = value),\n'
      '      children: const <Widget>[\n'
      '        AstryxToggleButton(value: \'production\', label: \'Production\'),\n'
      '        AstryxToggleButton(value: \'staging\', label: \'Staging\'),\n'
      '        AstryxToggleButton(value: \'dev\', label: \'Development\'),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/toggle_button_examples.dart
  'toggle_button_states':
      'class ToggleButtonStatesExample extends StatelessWidget {\n'
      '  const ToggleButtonStatesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // Disabled and loading both refuse the press. Loading also reports the wait\n'
      '    // to a screen reader, and keeps the button\'s width so the row cannot jump.\n'
      '    return const AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      wrap: true,\n'
      '      runGap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        AstryxToggleButton(label: \'Off\'),\n'
      '        AstryxToggleButton(label: \'On\', pressed: true),\n'
      '        AstryxToggleButton(label: \'Disabled\', enabled: false),\n'
      '        AstryxToggleButton(label: \'Saving\', pressed: true, loading: true),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
