  // examples/typography_examples.dart
  'typography_roles':
      'class TypographyRolesExample extends StatelessWidget {\n'
      '  const TypographyRolesExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = AstryxTheme.of(context);\n'
      '\n'
      '    // Fourteen roles. Each one is a size, a weight and a line height together —\n'
      '    // ask for the role and the three cannot come apart.\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        for (final role in AstryxTypeRole.values)\n'
      '          Builder(\n'
      '            builder: (context) {\n'
      '              final style = theme.textStyle(role);\n'
      '\n'
      '              return AstryxHStack(\n'
      '                gap: AstryxSpacingToken.spacing3,\n'
      '                align: AstryxStackAlign.end,\n'
      '                children: <Widget>[\n'
      '                  SizedBox(\n'
      '                    width: 92,\n'
      '                    child: AstryxText(\n'
      '                      role.name,\n'
      '                      type: AstryxTextType.code,\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                      maxLines: 1,\n'
      '                    ),\n'
      '                  ),\n'
      '                  SizedBox(\n'
      '                    width: 76,\n'
      '                    child: AstryxText(\n'
      '                      \'\${style.fontSize?.round()}px · \'\n'
      '                      \'\${style.fontWeight?.value}\',\n'
      '                      type: AstryxTextType.supporting,\n'
      '                      color: AstryxTextColor.secondary,\n'
      '                      maxLines: 1,\n'
      '                    ),\n'
      '                  ),\n'
      '                  Flexible(\n'
      '                    child: Text(\n'
      '                      \'The quick brown fox\',\n'
      '                      style: style,\n'
      '                      maxLines: 1,\n'
      '                      overflow: TextOverflow.ellipsis,\n'
      '                    ),\n'
      '                  ),\n'
      '                ],\n'
      '              );\n'
      '            },\n'
      '          ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/typography_examples.dart
  'typography_in_context':
      'class TypographyInContextExample extends StatelessWidget {\n'
      '  const TypographyInContextExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The roles doing their jobs. Nothing here names a size: the heading takes\n'
      '    // a level, everything else takes a type.\n'
      '    return AstryxCard(\n'
      '      child: AstryxVStack(\n'
      '        gap: AstryxSpacingToken.spacing3,\n'
      '        align: AstryxStackAlign.stretch,\n'
      '        children: <Widget>[\n'
      '          const AstryxHeading(\'Deployment failed\', level: 3),\n'
      '          const AstryxText(\n'
      '            \'The build finished, but the health check never went green. \'\n'
      '            \'Nothing was promoted.\',\n'
      '          ),\n'
      '          const AstryxText(\'Exit code\', type: AstryxTextType.label),\n'
      '          const AstryxText(\'137 — out of memory\', type: AstryxTextType.code),\n'
      '          const AstryxText(\n'
      '            \'Retried twice. Last attempt 4 minutes ago.\',\n'
      '            type: AstryxTextType.supporting,\n'
      '            color: AstryxTextColor.secondary,\n'
      '          ),\n'
      '          AstryxHStack(\n'
      '            gap: AstryxSpacingToken.spacing2,\n'
      '            children: <Widget>[\n'
      '              AstryxButton(label: \'Retry\', onPressed: () {}),\n'
      '              AstryxButton(\n'
      '                label: \'View log\',\n'
      '                variant: AstryxButtonVariant.secondary,\n'
      '                onPressed: () {},\n'
      '              ),\n'
      '            ],\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/visually_hidden_examples.dart
  'visually_hidden_live':
      'class VisuallyHiddenLiveExample extends StatefulWidget {\n'
      '  const VisuallyHiddenLiveExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<VisuallyHiddenLiveExample> createState() =>\n'
      '      _VisuallyHiddenLiveExampleState();\n'
      '}\n'
      '\n'
      'class _VisuallyHiddenLiveExampleState extends State<VisuallyHiddenLiveExample> {\n'
      '  static const int _limit = 40;\n'
      '\n'
      '  final TextEditingController _controller = TextEditingController();\n'
      '  int _remaining = _limit;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _controller.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The count is the announcement. There is no widget it could be the name\n'
      '    // of — the input is already named "Summary" — so the only way to report it\n'
      '    // is a region of its own.\n'
      '    final announcement = \'\$_remaining characters remaining\';\n'
      '\n'
      '    return AstryxVStack(\n'
      '      gap: AstryxSpacingToken.spacing3,\n'
      '      align: AstryxStackAlign.stretch,\n'
      '      children: <Widget>[\n'
      '        AstryxTextInput(\n'
      '          label: \'Summary\',\n'
      '          controller: _controller,\n'
      '          maxLength: _limit,\n'
      '          placeholder: \'What changed, in one line\',\n'
      '          onChanged: (value) =>\n'
      '              setState(() => _remaining = _limit - value.length),\n'
      '        ),\n'
      '        AstryxVisuallyHidden(\n'
      '          liveRegion: true,\n'
      '          child: Text(announcement),\n'
      '        ),\n'
      '        // The same string, painted, so this page can show what is otherwise\n'
      '        // only audible. A real form would not draw it twice.\n'
      '        AstryxText(\n'
      '          \'A screen reader hears: “\$announcement”\',\n'
      '          type: AstryxTextType.supporting,\n'
      '          color: AstryxTextColor.secondary,\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  // examples/visually_hidden_examples.dart
  'visually_hidden_space':
      'class VisuallyHiddenSpaceExample extends StatelessWidget {\n'
      '  const VisuallyHiddenSpaceExample({super.key});\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    // The hidden child sits between the two badges and measures `Size.zero`,\n'
      '    // so the row looks exactly as it would without it. A test pins that.\n'
      '    return const AstryxHStack(\n'
      '      gap: AstryxSpacingToken.spacing2,\n'
      '      children: <Widget>[\n'
      '        AstryxBadge(\'Queued\', variant: AstryxBadgeVariant.info),\n'
      '        AstryxVisuallyHidden(\n'
      '          child: Text(\'and it has been queued for eleven minutes\'),\n'
      '        ),\n'
      '        AstryxBadge(\'Building\', variant: AstryxBadgeVariant.warning),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
